$checks=0;$ok=static function(bool $v,string $m)use(&$checks):void{$checks++;if(!$v){fwrite(STDERR,"FAIL $checks: $m\n");exit(1);}};
$parent=json_decode(file_get_contents(__DIR__.'/../../../source/0.9.26-r3/genome/genome.json'),true,512,JSON_THROW_ON_ERROR);$kp=sodium_crypto_sign_keypair();$pub=sodium_crypto_sign_publickey($kp);$sec=sodium_crypto_sign_secretkey($kp);$otherKp=sodium_crypto_sign_keypair();$otherPub=sodium_crypto_sign_publickey($otherKp);$otherSec=sodium_crypto_sign_secretkey($otherKp);$nonce=bin2hex(random_bytes(32));
