$child2=KiComDerivativeGenome::build($parent,base64_encode($pub),$nonce);$ok($child2['id']===$unsigned['id'],'same inputs deterministic');$child3=KiComDerivativeGenome::build($parent,base64_encode($pub),bin2hex(random_bytes(32)));$ok($child3['id']!==$unsigned['id'],'fresh nonce changes identity');
